// 1. Input Validation & Configuration Check
int is_rejected = 0;

// Check configuration validity
if (sa_config.enter_rad < 0.0 || sa_config.exit_rad < 0.0 || 
    sa_config.enter_rad > ADCS_PI || sa_config.exit_rad > ADCS_PI ||
    sa_config.enter_rad > sa_config.exit_rad ||
    sa_config.acqquire_gain_nm_rad < 0.0 || sa_config.track_gain_nm_rad < 0.0 ||
    sa_config.torque_limit_nm <= 0.0 || sa_config.max_slew_nm_per_cycle <= 0.0 ||
    sa_config.coast_decay < 0.0 || sa_config.coast_decay > 1.0 ||
    sa_config.acquire_samples < 1 || sa_config.acquire_samples > 20 ||
    sa_config.max_coast_samples < 1 || sa_config.max_coast_samples >= sa_config.max_bad_samples ||
    sa_config.max_bad_samples < 1 || sa_config.max_bad_samples > 20) {
    is_rejected = 1;
}

// Check input validity
if (!is_rejected) {
    if (sa_input.valid != 1 || sa_input.measured_body == NULL || sa_input.target_body == NULL) {
        is_rejected = 1;
    } else {
        if (!adcs_is_finite_vec3(sa_input.measured_body) || !adcs_is_finite_vec3(sa_input.target_body)) {
            is_rejected = 1;
        } else {
            double n_m = adcs_vec3_norm(sa_input.measured_body);
            double n_t = adcs_vec3_norm(sa_input.target_body);
            if (n_m <= ADCS_EPS_NORM || n_t <= ADCS_EPS_NORM) {
                is_rejected = 1;
            }
        }
    }
}

// Handle Rejection
if (is_rejected) {
    sa_state.good_samples = 0;
    sa_state.bad_samples++;

    if (sa_state.mode == SA_TRACK || sa_state.mode == SA_COAST) {
        sa_output.mode = SA_COAST;
        sa_state.mode = SA_COAST;
        sa_state.coast_samples++;

        sa_output.torque_nm = adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0,0,0};
        sa_output.slew_mask = 0;

        sa_state.previous_torque_nm = sa_output.torque_nm;

        if (sa_state.bad_samples >= sa_config.max_bad_samples) {
            sa_output.mode = SA_FAULT;
            sa_state.mode = SA_FAULT;
        }
        return;
    } else {
        if (sa_state.mode == SA_OFF) {
            sa_state.mode = SA_SEARCH;
        }

        if (sa_state.bad_samples >= sa_config.max_bad_samples) {
            sa_state.mode = SA_FAULT;
        }

        sa_output.mode = sa_state.mode;
        sa_output.torque_nm = (adcs_vec3_t){0,0,0};
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0,0,0};
        sa_output.slew_mask = 0;

        sa_state.previous_torque_nm = sa_output.torque_nm;
        return;
    }
}

// 2. Vector Normalization and Angle Calculation
adcs_vec3_t norm_measured, norm_target;
adcs_vec3_normalize(sa_input.measured_body, ADCS_EPS_NORM, &norm_measured);
adcs_vec3_normalize(sa_input.target_body, ADCS_EPS_NORM, &norm_target);

adcs_vec3_t cross = adcs_vec3_cross(&norm_measured, &norm_target);
double dot = adcs_vec3_dot(&norm_measured, &norm_target);
double angle = atan2(adcs_vec3_norm(&cross), dot);

// Determine Rotation Axis
adcs_vec3_t rot_axis;

if (dot < -1.0 + ADCS_EPS_COLLINEAR) {
    double align_x = fabs(norm_measured.x);
    double align_y = fabs(norm_measured.y);
    double align_z = fabs(norm_measured.z);

    double min_align = align_x;
    int idx = 0;

    if (align_y < min_align) {
        min_align = align_y;
        idx = 1;
    }
    if (align_z < min_align) {
        min_align = align_z;
        idx = 2;
    }

    adcs_vec3_t basis;
    if (idx == 0) basis = (adcs_vec3_t){1,0,0};
    else if (idx == 1) basis = (adcs_vec3_t){0,1,0};
    else basis = (adcs_vec3_t){0,0,1};

    cross = adcs_vec3_cross(&norm_measured, &basis);
    adcs_vec3_normalize(&cross, ADCS_EPS_NORM, &rot_axis);
    angle = ADCS_PI;
} else {
    adcs_vec3_normalize(&cross, ADCS_EPS_NORM, &rot_axis);
}

// 3. Mode Transition Logic
sa_mode_t new_mode = sa_state.mode;

if (sa_state.mode == SA_OFF) {
    new_mode = SA_SEARCH;
    sa_state.mode = SA_SEARCH;
}

switch (new_mode) {
    case SA_SEARCH:
        if (angle <= sa_config.enter_rad) {
            new_mode = SA_ACQUIRE;
            sa_state.good_samples = 0;
            sa_state.coast_samples = 0;
        }
        break;

    case SA_ACQUIRE:
        if (angle <= sa_config.enter_rad) {
            sa_state.good_samples++;
            if (sa_state.good_samples >= sa_config.acquire_samples) {
                new_mode = SA_TRACK;
            }
        } else {
            new_mode = SA_SEARCH;
            sa_state.good_samples = 0;
            sa_state.coast_samples = 0;
        }
        break;

    case SA_TRACK:
        if (angle >= sa_config.exit_rad) {
            new_mode = SA_SEARCH;
            sa_state.good_samples = 0;
            sa_state.coast_samples = 0;
        }
        break;

    case SA_COAST:
        if (angle < sa_config.exit_rad) {
            new_mode = SA_TRACK;
            sa_state.coast_samples = 0;
        }
        break;

    default:
        break;
}

sa_state.mode = new_mode;

// 4. Torque Generation
double gain = 0.0;
if (new_mode == SA_TRACK) {
    gain = sa_config.track_gain_nm_rad;
} else {
    gain = sa_config.acquire_gain_nm_rad;
}

adcs_vec3_t raw_torque = adcs_vec3_scale(&rot_axis, gain * angle);

double mag = adcs_vec3_norm(&raw_torque);
if (mag > sa_config.torque_limit_nm) {
    raw_torque = adcs_vec3_scale(&raw_torque, sa_config.torque_limit_nm / mag);
}

unint32 slew_mask = 0;
adcs_vec3_t limited_torque = raw_torque;
double prev_t = sa_state.previous_torque_nm;

for (int i = 0; i < 3; i++) {
    double curr_val = (i==0)?limited_torque.x : (i==1)?limited_torque.y : limited_torque.z;
    double prev_val = (i==0)?prev_t.x : (i==1)?prev_t.y : prev_t.z;
    double diff = curr_val - prev_val;
    double limit = sa_config.max_slew_nm_per_cycle;

    if (diff > limit) {
        limited_torque = (i==0) ? (adcs_vec3_t){prev_val + limit, limited_torque.y, limited_torque.z} :
                   (i==1) ? (adcs_vec3_t){limited_torque.x, prev_val + limit, limited_torque.z} :
                            (adcs_vec3_t){limited_torque.x, limited_torque.y, prev_val + limit};
        slew_mask |= (1U << i);
    } else if (diff < -limit) {
        limited_torque = (i==0) ? (adcs_vec3_t){prev_val - limit, limited_torque.y, limited_torque.z} :
                   (i==1) ? (adcs_vec3_t){limited_torque.x, prev_val - limit, limited_torque.z} :
                            (adcs_vec3_t){limited_torque.x, limited_torque.y, prev_val - limit};
        slew_mask |= (1U << i);
    }
}

// 5. State Updates and Output
sa_output.mode = sa_state.mode;
sa_output.error_rad = angle;
sa_output.rotation_axis = rot_axis;
sa_output.torque_nm = limited_torque;
sa_output.slew_mask = slew_mask;

sa_state.bad_samples = 0;

if (sa_state.mode != SA_COAST) {
    sa_state.coast_samples = 0;
}

sa_state.previous_torque_nm = limited_torque;

