int sample_rejected = !config_valid || !input_valid;

if (sample_rejected) {
    sa_state.good_samples = 0;
    sa_state.bad_samples++;

    if (sa_state.bad_samples >= sa_config.max_bad_samples) {
        sa_state.mode = SA_FAULT;
    } else {
        if (sa_state.mode == SA_COAST) {
            sa_output.torque_nm = adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);
            sa_state.coast_samples++;
        } else if (sa_state.mode == SA_TRACK) {
            sa_state.mode = SA_COAST;
            sa_output.torque_nm = adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);
            sa_state.coast_samples = 1;
        } else {
            // SEARCH, ACQUIRE, OFF remain in current mode (or OFF stays OFF? OFF is transient)
            // OFF is not a persistent mode for storage really, but if stored, it stays.
            // But rejected samples in OFF? 
            // "An accepted sample in OFF is processed as SEARCH". Rejection in OFF?
            // If valid=0, it's rejected. If in OFF, it stays OFF?
            // The prompt doesn't specify OFF behavior on rejection explicitly other than "rejected sample ... increments bad_samples".
            // Assuming mode stays same.
        }
    }
    return;
}

// Accepted sample
sa_state.bad_samples = 0;
sa_state.coast_samples = 0;
sa_state.good_samples++;

adcs_vec3_t norm_meas, norm_target;
if (adcs_vec3_normalize(sa_input.measured_body, ADCS_EPS_NORM, &norm_meas) != ADCS_OK) {
    /* Should not happen as input was validated above */
    return; 
}
if (adcs_vec3_normalize(sa_input.target_body, ADCS_EPS_NORM, &norm_target) != ADCS_OK) {
    /* Should not happen as input was validated above */
    return;
}

double dot_val = adcs_vec3_dot(&norm_meas, &norm_target);
adcs_vec3_t cross_val = adcs_vec3_cross(&norm_meas, &norm_target);
double cross_norm = adcs_vec3_norm(&cross_val);

double angle = atan2(cross_norm, dot_val);
sa_output.error_rad = angle;

adcs_vec3_t axis;
if (angle > (ADCS_PI - ADCS_EPS_COLLINEAR)) {
    double d_x = fabs(norm_meas.x);
    double d_y = fabs(norm_meas.y);
    double d_z = fabs(norm_meas.z);

    int idx = 0;
    double min_val = d_x;
    if (d_y < min_val) {
        min_val = d_y;
        idx = 1;
    }
    if (d_z < min_val) {
        min_val = d_z;
        idx = 2;
    }

    adcs_vec3_t basis;
    if (idx == 0) basis = (adcs_vec3_t){1, 0, 0};
    else if (idx == 1) basis = (adcs_vec3_t){0, 1, 0};
    else basis = (adcs_vec3_t){0, 0, 1};

    axis = adcs_vec3_cross(&norm_meas, &basis);
    double n = adcs_vec3_norm(&axis);
    if (n > ADCS_EPS_NORM) {
        axis = adcs_vec3_scale(&axis, 1.0 / n);
    } else {
        axis = (adcs_vec3_t){1, 0, 0};
    }
} else {
    axis = cross_val;
    double n = adcs_vec3_norm(&axis);
    if (n > ADCS_EPS_NORM) {
        axis = adcs_vec3_scale(&axis, 1.0 / n);
    } else {
        axis = (adcs_vec3_t){0, 0, 0};
    }
}
sa_output.rotation_axis = axis;

sa_mode_t next_mode = sa_state.mode;

switch (sa_state.mode) {
    case SA_OFF:
        next_mode = SA_SEARCH;
        break;
    case SA_SEARCH:
        if (angle <= sa_config.enter_rad) {
            next_mode = SA_ACQUIRE;
            sa_state.good_samples = 1;
        } else {
            next_mode = SA_SEARCH;
        }
        break;
    case SA_ACQUIRE:
        if (angle <= sa_config.enter_rad) {
            sa_state.good_samples++;
            if (sa_state.good_samples >= sa_config.acquire_samples) {
                next_mode = SA_TRACK;
                sa_state.good_samples = 0;
            } else {
                next_mode = SA_ACQUIRE;
            }
        } else {
            next_mode = SA_SEARCH;
            sa_state.good_samples = 0;
        }
        break;
    case SA_TRACK:
        if (angle >= sa_config.exit_rad) {
            next_mode = SA_SEARCH;
        } else {
            next_mode = SA_TRACK;
        }
        break;
    case SA_COAST:
        if (angle < sa_config.exit_rad) {
            next_mode = SA_TRACK;
        } else {
            next_mode = SA_SEARCH;
        }
        break;
    case SA_FAULT:
    default:
        next_mode = sa_state.mode;
        break;
}

sa_output.mode = next_mode;
sa_state.mode = next_mode;

double gain;
if (next_mode == SA_TRACK) {
    gain = sa_config.track_gain_nm_rad;
} else {
    gain = sa_config.acquire_gain_nm_rad;
}

adcs_vec3_t raw_torque = adcs_vec3_scale(&axis, -gain * angle);

double mag = adcs_vec3_norm(&raw_torque);
if (mag > sa_config.torque_limit_nm) {
    raw_torque = adcs_vec3_scale(&raw_torque, sa_config.torque_limit_nm / mag);
}

double prev_tx = sa_state.previous_torque_nm.x;
double prev_ty = sa_state.previous_torque_nm.y;
double prev_tz = sa_state.previous_torque_nm.z;

double raw_tx = raw_torque.x;
double raw_ty = raw_torque.y;
double raw_tz = raw_torque.z;

double lim_tx, lim_ty, lim_tz;
uint32_t slew_mask = 0;

double dx = raw_tx - prev_tx;
if (fabs(dx) > sa_config.max_slew_nm_per_cycle) {
    dx = copysign(sa_config.max_slew_nm_per_cycle, dx);
    slew_mask |= 1U;
}
lim_tx = prev_tx + dx;

double dy = raw_ty - prev_ty;
if (fabs(dy) > sa_config.max_slew_nm_per_cycle) {
    dy = copysign(sa_config.max_slew_nm_per_cycle, dy);
    slew_mask |= 2U;
}
lim_ty = prev_ty + dy;

double dz = raw_tz - prev_tz;
if (fabs(dz) > sa_config.max_slew_nm_per_cycle) {
    dz = copysign(sa_config.max_slew_nm_per_cycle, dz);
    slew_mask |= 4U;
}
lim_tz = prev_tz + dz;

sa_state.previous_torque_nm = (adcs_vec3_t){lim_tx, lim_ty, lim_tz};
sa_output.torque_nm = (adcs_vec3_t){lim_tx, lim_ty, lim_tz};
sa_output.slew_mask = slew_mask;
